import ast
import json
from collections import Counter

def task_func(file_pointer):
    # Load JSON data from file pointer
    data = json.load(file_pointer)

    # Initialize counter for keys
    key_counter = Counter()

    # Iterate through each item in the data
    for item in data:
        # If item is a string, evaluate it to get a dictionary
        if isinstance(item, str):
            try:
                item = ast.literal_eval(item)
            except (ValueError, SyntaxError):
                # If evaluation fails, skip this item
                continue

        # If item is a dictionary, count its keys
        if isinstance(item, dict):
            for key in item.keys():
                key_counter[key] += 1

    return key_counter

