import json

# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(ip_address):
    # Try to parse input as JSON if it's a string
    try:
        if isinstance(ip_address, str):
            data = json.loads(ip_address)
        else:
            data = ip_address
    except (json.JSONDecodeError, TypeError):
        data = ip_address

    # Extract IP address from JSON data if applicable
    ip = None
    if isinstance(data, dict):
        # Check common keys for IP address
        for key in ['ip', 'ipAddress', 'public_ip', 'publicIp', 'IP', 'IpAddress']:
            if key in data and isinstance(data[key], str):
                ip = data[key]
                break
        # If not found, search for any string value matching IP pattern
        if ip is None:
            for value in data.values():
                if isinstance(value, str) and re.fullmatch(IP_REGEX, value):
                    ip = value
                    break
    elif isinstance(data, str):
        ip = data
    else:
        ip = str(data)

    # Validate IP address format using regex
    if not ip or not re.fullmatch(IP_REGEX, ip):
        return 'Invalid IP address received'

    # Validate each octet is within 0-255 range
    octets = ip.split('.')
    if len(octets) != 4:
        return 'Invalid IP address received'

    for octet in octets:
        try:
            num = int(octet)
            if num < 0 or num > 255:
                return 'Invalid IP address received'
        except ValueError:
            return 'Invalid IP address received'

    return ip
