            response = requests.get(f'http://ip-api.com/json/{ip_address}', timeout=10)
            if response.status_code == 200:
                data = response.json()
                if data.get('status') == 'success':
                    result[domain] = data
                else:
                    result[domain] = None
            else:
                result[domain] = None
        except Exception:
            result[domain] = None

    return result
